package jop.generate

import jop.config._

/** Pin assignment: maps an FPGA pin to a Verilog port name */
case class PinAssignment(fpgaPin: String, verilogPort: String)

/**
 * Shared pin resolution for constraint generators (QSF, XDC).
 *
 * Resolution chain:
 *   DeviceType.verilogPins: verilogPort -> deviceSignal
 *   BoardDevice.mapping: deviceSignal -> connectorRef
 *   SystemAssembly.resolvePin: connectorRef -> fpgaPin
 */
object PinResolver {

  /** SDR SDRAM pin map: verilogPort -> deviceSignal.
    * Verilog ports generated by SpinalHDL SdramInterface. */
  private val sdramPinMap: Map[String, String] = Map(
    "sdram_CSn" -> "CS_n", "sdram_RASn" -> "RAS_n",
    "sdram_CASn" -> "CAS_n", "sdram_WEn" -> "WE_n",
    "sdram_CKE" -> "CKE",
    "sdram_BA[0]" -> "BA0", "sdram_BA[1]" -> "BA1"
  ) ++ (0 to 12).map(i => s"sdram_ADDR[$i]" -> s"A$i") ++
    // Up to 32 bits wide: the Colorlight i5's EM638325BK-6H is a 32-bit part
    // (BmbSdramCtrlWide drives it 1:1). Entries the board does not map are
    // dropped by the lookup below, so a 16-bit board is unaffected.
    (0 to 31).map(i => s"sdram_DQ[$i]" -> s"DQ$i") ++
    (0 to 3).map(i => s"sdram_DQM[$i]" -> s"DQM$i")

  /** The FPGA pin of the board clock the design takes in (`inputClock`).
    * Refuses a clock whose pin resolves to no FPGA pin: an unassigned clock
    * input is left for the fitter to place wherever it likes.
    *
    * Until 2026-11-02 this took the first `CLOCK_*` device of ANY board in the
    * assembly, while the frequency came from the first one on the FPGA board:
    * two lookups that agreed only because no other board declared a clock. */
  def clockFpgaPin(design: BoardDesign): String = {
    val c = design.inputClock
    design.assembly.resolvePin(c.pin).getOrElse(throw new IllegalArgumentException(
      s"${design.designName}: clock ${c.name} is on ${c.pin}, which is no FPGA pin of ${design.assembly.name}"))
  }

  /** Resolve reset FPGA pin from SWITCH device's "reset" mapping */
  def resetFpgaPin(assembly: SystemAssembly): Option[String] =
    assembly.allDevices
      .filter(_.part == "SWITCH")
      .flatMap(_.mapping.get("reset"))
      .flatMap(assembly.resolvePin)
      .headOption

  /** Resolve SDRAM clock FPGA pin */
  def sdramClockFpgaPin(assembly: SystemAssembly): Option[String] =
    assembly.memoryDevices
      .filter(_._2.memType == MemoryType.SDRAM_SDR)
      .headOption
      .flatMap { case (_, md) => assembly.pinMapping(md.name).get("CLK") }

  /** Resolve LED pins, sorted by index */
  def ledPins(assembly: SystemAssembly): Seq[PinAssignment] = {
    // With SystemAssembly.ledBoard set, ONLY that board's LEDs: a module's own
    // LED and a base board's both call theirs led0, and merging by name would
    // let whichever came last win. Unset, the original merge.
    val ledMappings = assembly.ledBoard match {
      case Some(_) =>
        assembly.ledSourceBoard.devices.filter(_.part == "LED").flatMap(_.mapping.flatMap {
          case (signal, ref) => assembly.resolvePin(ref).map(signal -> _)
        }).toMap
      case None => assembly.allPinMappings("LED")
    }
    ledMappings.toSeq
      .sortBy { case (signal, _) => signal.stripPrefix("led").toInt }
      .map { case (signal, fpgaPin) =>
        PinAssignment(fpgaPin, s"led[${signal.stripPrefix("led")}]")
      }
  }

  /** Resolve SDR SDRAM pins from memory device mapping */
  def sdramPins(assembly: SystemAssembly): Seq[PinAssignment] = {
    val sdramDevices = assembly.memoryDevices.filter(_._2.memType == MemoryType.SDRAM_SDR)
    sdramDevices.headOption match {
      case Some((_, md)) =>
        val devicePins = assembly.pinMapping(md.name)
        sdramPinMap.flatMap { case (verilogPort, deviceSignal) =>
          devicePins.get(deviceSignal).map(PinAssignment(_, verilogPort))
        }.toSeq
      case None => Seq.empty
    }
  }

  /** Resolve device pins from DeviceType.verilogPins.
   *  Each DeviceInstance with a devicePart is resolved through the assembly. */
  def devicePins(assembly: SystemAssembly,
                 devices: Map[String, DeviceInstance]): Seq[PinAssignment] =
    devices.values.toSeq.flatMap { inst =>
      for {
        part <- inst.devicePart.toSeq
        boardPins = assembly.pinMapping(part)
        (verilogPort, deviceSignal) <- inst.deviceType.verilogPins(inst.params)
        fpgaPin <- boardPins.get(deviceSignal)
      } yield PinAssignment(fpgaPin, verilogPort)
    }
}
